  returns: "text-[color:var(--docs-interaction-sig-type,#76502d)] dark:text-[color:var(--docs-interaction-sig-type,#e1c29f)]",
} as const;

function PunctToken({ text }: { text: string }) { return <span data-sig-token="punct" className={SIG_TOKEN_CLASS.punct}>{text}</span>; }

