      note.end = lines.length;
    }
  };
  lines.push({ content: [nameToken, <PunctToken key="(" text="(" />] }); emitParams(params, 1, operation.name, [], notes); lines.push({ content: [<PunctToken key=")" text=")" />, returnsToken] }); return { lines, notes };
}

function NoteRow({ note, depth }: { note: ParamNote; depth: number }) {
  return <LinkTarget linkKey={note.key} data-param-note={note.key} data-note-indent={depth} className="relative block min-w-0 px-3 py-2.5 text-xs motion-reduce:transition-none">
