  return <div data-note-group={note.key} data-tree-depth={depth}><NoteRow note={note} depth={depth} />{note.children.length > 0 && <div data-note-children="true" className="relative ml-4 border-l border-solid border-[color:var(--docs-operations-tree)] pl-3">{note.children.map((child) => <NoteGroup key={child.key} note={child} depth={depth + 1} />)}</div>}</div>;
}

