      @media(prefers-reduced-motion:reduce){[data-docs-block-type="interaction-surface"] *{scroll-behavior:auto!important;transition-duration:.01ms!important}}
    `}</style>
    <header data-operations-header="true" className="relative overflow-hidden border-b border-solid border-[color:var(--docs-operations-rule)] bg-[color:var(--docs-operations-header-bg)] px-5 py-4 text-[color:var(--docs-operations-header-fg)]">
